use std::path::{Path, PathBuf};
use std::fs;
use std::time::{Duration, Instant};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::collections::HashMap;

const MAX_RETRIES: u32 = 3;
const RATE_LIMIT_WINDOW: Duration = Duration::from_secs(60);
const MAX_REQUESTS_PER_WINDOW: u64 = 100;

#[derive(Clone, Debug)]
pub struct DbConfig {
    pub data_dir: PathBuf,
    pub migration_dir: PathBuf,
    pub log_dir: PathBuf,
}

pub struct RateLimiter {
    request_count: AtomicU64,
    window_start: Instant,
}

impl RateLimiter {
    pub fn new() -> Self {
        Self {
            request_count: AtomicU64::new(0),
            window_start: Instant::now(),
        }
    }

    pub fn check_rate_limit(&self) -> Result<(), DriverError> {
        let elapsed = self.window_start.elapsed();
        if elapsed > RATE_LIMIT_WINDOW {
            self.request_count.store(0, Ordering::SeqCst);
        }
        let count = self.request_count.fetch_add(1, Ordering::SeqCst);
        if count >= MAX_REQUESTS_PER_WINDOW {
            return Err(DriverError::RateLimited);
        }
        Ok(())
    }
}

#[derive(Debug)]
pub enum DriverError {
    IoError(std::io::Error),
    RateLimited,
    NotFound(String),
    InvalidPath(String),
    RetryExhausted,
}

impl From<std::io::Error> for DriverError {
    fn from(e: std::io::Error) -> Self {
        DriverError::IoError(e)
    }
}

pub struct DatabaseDriver {
    config: DbConfig,
    rate_limiter: Arc<RateLimiter>,
}

impl DatabaseDriver {
    pub fn new(config: DbConfig) -> Self {
        Self {
            config,
            rate_limiter: Arc::new(RateLimiter::new()),
        }
    }

    fn sanitize_collection_name(&self, name: &str) -> Result<String, DriverError> {
        if name.is_empty() || name.len() > 128 {
            return Err(DriverError::InvalidPath("Invalid collection name length".into()));
        }
        // Allow alphanumeric, underscore, hyphen, and dot
        if !name.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '.') {
            return Err(DriverError::InvalidPath("Invalid characters in collection name".into()));
        }
        Ok(name.to_string())
    }

    fn resolve_data_path(&self, collection: &str) -> Result<PathBuf, DriverError> {
        let sanitized = self.sanitize_collection_name(collection)?;
        let candidate = self.config.data_dir.join(&sanitized);
        // Canonicalize to prevent traversal
        let canonical = fs::canonicalize(&candidate)
            .map_err(|_| DriverError::NotFound(format!("Collection '{}' not found", sanitized)))?;
        let base = fs::canonicalize(&self.config.data_dir)?;
        if !canonical.starts_with(&base) {
            return Err(DriverError::InvalidPath("Path traversal detected".into()));
        }
        Ok(canonical)
    }

    fn retry_operation<F, T>(&self, mut operation: F) -> Result<T, DriverError>
    where
        F: FnMut() -> Result<T, DriverError>,
    {
        let mut last_err = DriverError::RetryExhausted;
        for attempt in 0..MAX_RETRIES {
            match operation() {
                Ok(val) => return Ok(val),
                Err(DriverError::IoError(_)) if attempt < MAX_RETRIES - 1 => {
                    std::thread::sleep(Duration::from_millis(100 * (attempt as u64 + 1)));
                    continue;
                }
                Err(e) => {
                    last_err = e;
                    break;
                }
            }
        }
        Err(last_err)
    }

    pub fn list_collections(&self) -> Result<Vec<String>, DriverError> {
        self.rate_limiter.check_rate_limit()?;
        self.retry_operation(|| {
            let entries = fs::read_dir(&self.config.data_dir)?;
            let mut collections = Vec::new();
            for entry in entries {
                let entry = entry?;
                if entry.file_type()?.is_dir() {
                    if let Some(name) = entry.file_name().to_str() {
                        collections.push(name.to_string());
                    }
                }
            }
            Ok(collections)
        })
    }

    pub fn list_documents(&self, collection: &str) -> Result<Vec<String>, DriverError> {
        self.rate_limiter.check_rate_limit()?;
        let path = self.resolve_data_path(collection)?;
        self.retry_operation(|| {
            let entries = fs::read_dir(&path)?;
            let mut documents = Vec::new();
            for entry in entries {
                let entry = entry?;
                let file_name = entry.file_name();
                let name = file_name.to_string_lossy().to_string();
                documents.push(name);
            }
            Ok(documents)
        })
    }

    pub fn get_diagnostics(&self, scope: &str) -> Result<HashMap<String, Vec<String>>, DriverError> {
        self.rate_limiter.check_rate_limit()?;
        let mut result = HashMap::new();

        let dirs_to_scan: Vec<(&str, &Path)> = match scope {
            "all" => vec![
                ("data", &self.config.data_dir),
                ("migrations", &self.config.migration_dir),
                ("logs", &self.config.log_dir),
            ],
            "data" => vec![("data", &self.config.data_dir)],
            "migrations" => vec![("migrations", &self.config.migration_dir)],
            "logs" => vec![("logs", &self.config.log_dir)],
            other => {
                // Treat as a relative path under data_dir for sub-collection diagnostics
                let resolved = self.resolve_diagnostic_path(other)?;
                let entries = self.scan_directory_recursive(&resolved, 3)?;
                result.insert(other.to_string(), entries);
                return Ok(result);
            }
        };

        for (label, dir) in dirs_to_scan {
            let entries = self.scan_directory_recursive(dir, 2)?;
            result.insert(label.to_string(), entries);
        }
        Ok(result)
    }

    fn resolve_diagnostic_path(&self, relative: &str) -> Result<PathBuf, DriverError> {
        // For diagnostics, we allow dotted notation: "collection.subcollection"
        let parts: Vec<&str> = relative.split('.').collect();
        let mut path = self.config.data_dir.clone();
        for part in &parts {
            // Validate each segment individually
            if part.is_empty() || part.contains('/') || part.contains('\\') {
                return Err(DriverError::InvalidPath("Invalid diagnostic path segment".into()));
            }
            path = path.join(part);
        }
        // Canonicalize and verify the path is within data_dir
        let canonical = fs::canonicalize(&path)
            .map_err(|_| DriverError::NotFound(format!("Diagnostic path '{}' not found", relative)))?;
        let base = fs::canonicalize(&self.config.data_dir)?;
        if !canonical.starts_with(&base) {
            return Err(DriverError::InvalidPath("Path traversal detected in diagnostic path".into()));
        }
        Ok(canonical)
    }

    fn scan_directory_recursive(&self, dir: &Path, max_depth: u32) -> Result<Vec<String>, DriverError> {
        if max_depth == 0 {
            return Ok(vec![format!("[truncated at depth limit]")]);
        }
        let mut results = Vec::new();
        if dir.is_dir() {
            let entries = fs::read_dir(dir)?;
            for entry in entries {
                let entry = entry?;
                let path = entry.path();
                let display = path.strip_prefix(&self.config.data_dir)
                    .or_else(|_| path.strip_prefix(&self.config.migration_dir))
                    .or_else(|_| path.strip_prefix(&self.config.log_dir))
                    .unwrap_or(&path)
                    .to_string_lossy()
                    .to_string();
                results.push(display.clone());
                if path.is_dir() {
                    let sub = self.scan_directory_recursive(&path, max_depth - 1)?;
                    results.extend(sub);
                }
            }
        }
        Ok(results)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn test_rate_limiter() {
        let limiter = RateLimiter::new();
        for _ in 0..MAX_REQUESTS_PER_WINDOW {
            assert!(limiter.check_rate_limit().is_ok());
        }
        assert!(limiter.check_rate_limit().is_err());
    }
}
